#!/bin/sh
# Synthesized ambient drone bed (no third-party licence). Output: sources/music/drone_bed.wav (48 kHz)
mkdir -p sources/music
ffmpeg -v error -y -f lavfi -i "aevalsrc='0.20*sin(2*PI*55*t)*(0.55+0.45*sin(2*PI*0.031*t)) + 0.12*sin(2*PI*82.41*t)*(0.5+0.5*sin(2*PI*0.023*t+1.3)) + 0.09*sin(2*PI*110*t)*(0.5+0.5*sin(2*PI*0.041*t+2.1)) + 0.06*sin(2*PI*130.81*t)*(0.5+0.5*sin(2*PI*0.017*t+0.4)) + 0.05*sin(2*PI*164.81*t)*(0.5+0.5*sin(2*PI*0.029*t+2.8)) + 0.035*sin(2*PI*220*t)*pow(0.5+0.5*sin(2*PI*0.5*t),8)|0.20*sin(2*PI*55.2*t)*(0.55+0.45*sin(2*PI*0.029*t+0.5)) + 0.12*sin(2*PI*82.6*t)*(0.5+0.5*sin(2*PI*0.027*t+0.2)) + 0.09*sin(2*PI*110.3*t)*(0.5+0.5*sin(2*PI*0.037*t+1.1)) + 0.06*sin(2*PI*131*t)*(0.5+0.5*sin(2*PI*0.019*t+1.9)) + 0.05*sin(2*PI*165*t)*(0.5+0.5*sin(2*PI*0.033*t+0.9)) + 0.035*sin(2*PI*220.4*t)*pow(0.5+0.5*sin(2*PI*0.5*t+0.2),8)':s=44100:d=890" -f lavfi -i "anoisesrc=color=brown:amplitude=0.25:d=890:r=44100" -filter_complex "[1:a]lowpass=f=350,highpass=f=40,volume=0.5,aformat=channel_layouts=stereo[n];[0:a][n]amix=inputs=2:normalize=0,aecho=0.6:0.5:120|190:0.25|0.18,lowpass=f=3000,afade=t=in:d=4,afade=t=out:st=880:d=10,loudnorm=I=-24:TP=-3,aresample=48000[m]" -map "[m]" -c:a pcm_s16le sources/music/drone_bed.wav
